import {approveDonation,configureCash,cashSettings} from '../server/cash';
import {gmAuthorized,gmSummary,gmDetail,gmMutate} from '../server/gm';
import {ITEMS,CLASSES,ZONES} from '../shared/content';
import {createWorld,migrateWorld,applyInput,newPlayer,snapshot,tickWorld} from '../server/engine';
import {guestIdentity,digest} from '../server/auth';
import {accountFor,changeAccount,ownedPlayer,roster} from '../shared/accounts';
import type {Input,World} from '../shared/types';
interface Env {REALM:DurableObjectNamespace;ASSETS:Fetcher;DB?:D1Database;GM_TOKEN?:string}
const reply=(value:unknown,status=200,headers:Record<string,string>={})=>Response.json(value,{status,headers:{'Cache-Control':'no-store',...headers}});
export class AetheriaRealm {
 private world:World;private gmToken:string;
 private sessions=new Map<WebSocket,{id:string;last:number}>();
 private timer:ReturnType<typeof setInterval>|null=null;
 private saved=0;private broadcastAt=0;
 constructor(private state:DurableObjectState,env:Env){this.gmToken=env.GM_TOKEN||'';state.storage.sql.exec('CREATE TABLE IF NOT EXISTS realm (id INTEGER PRIMARY KEY, data TEXT NOT NULL)');const rows=[...state.storage.sql.exec<{data:string}>('SELECT data FROM realm WHERE id=1')];this.world=rows.length?JSON.parse(rows[0].data):createWorld(Date.now());migrateWorld(this.world,Date.now());this.world.tick=Date.now();if(!rows.length&&env.DB)state.blockConcurrencyWhile(async()=>{const old=await env.DB!.prepare('SELECT data FROM realms WHERE id=?').bind('aetheria').first<{data:string}>();if(old){this.world=JSON.parse(old.data);migrateWorld(this.world,Date.now());this.world.tick=Date.now();this.save();}});for(const ws of state.getWebSockets()){const attachment=ws.deserializeAttachment() as {id:string};if(this.world.players[attachment.id])this.sessions.set(ws,{id:attachment.id,last:0});}if(this.sessions.size)this.start();}
 private save(){this.state.storage.sql.exec('INSERT INTO realm (id,data) VALUES (1,?) ON CONFLICT(id) DO UPDATE SET data=excluded.data',JSON.stringify(this.world));this.saved=Date.now();}
 private start(){if(this.timer)return;this.timer=setInterval(()=>{const now=Date.now();tickWorld(this.world,now);if(now-this.broadcastAt>=100){this.broadcast();this.broadcastAt=now;}if(now-this.saved>=5000)this.save();if(!this.sessions.size){clearInterval(this.timer!);this.timer=null;this.save();}},50);}
 private broadcast(){for(const [ws,s] of this.sessions){const p=this.world.players[s.id];if(!p){ws.close(1000,'Character removed');this.sessions.delete(ws);continue;}try{ws.send(JSON.stringify(snapshot(this.world,p,Date.now())));}catch{this.sessions.delete(ws);}}}
 private chat(id:string,text:unknown){const p=this.world.players[id],now=Date.now();if(!p||typeof text!=='string')return;const value=text.replace(/[<>\x00-\x1f]/g,'').trim().slice(0,120);if(!value||now-(this.world.chat.filter(c=>c.id.startsWith(id+':')).at(-1)?.time||0)<900)return;this.world.chat.push({id:id+':'+crypto.randomUUID(),name:p.name,text:value,time:now,zone:p.zone,playerId:p.id});this.world.chat=this.world.chat.slice(-60);this.save();this.broadcast();}
 async fetch(request:Request){const url=new URL(request.url),origin=request.headers.get('Origin');if(origin&&new URL(origin).host!==url.host)return reply({error:'잘못된 요청입니다.'},403);try{if(url.pathname==='/api/auth/session')return reply({googleEnabled:false,provider:'guest',profile:null});if(url.pathname==='/api/auth/google')return Response.redirect(new URL('/?login=setup',request.url),302);if(url.pathname.startsWith('/api/gm/'))return await this.gmRequest(request,url);let auth=await guestIdentity(request);const token=auth?.token||crypto.randomUUID();auth??={token,id:await digest(token)};const headers={'Set-Cookie':`aetheria_guest=${token}; Path=/; HttpOnly; SameSite=Lax; Max-Age=31536000${url.protocol==='https:'?'; Secure':''}`};const account=accountFor(this.world,auth.id);
 if(url.pathname==='/api/account'){if(request.method==='GET')return reply(roster(this.world,auth.id),200,headers);if(request.method!=='POST')return reply({error:'잘못된 요청입니다.'},405);const body=await this.body(request);if(body.action==='delete'){const p=ownedPlayer(this.world,auth.id,body.characterId);if(!p||body.confirm!==p.name)return reply({error:'삭제할 캐릭터의 이름을 정확히 입력하세요.'},400);for(const [ws,s] of this.sessions)if(s.id===p.id){ws.close(1000,'Character removed');this.sessions.delete(ws);}}const result=changeAccount(this.world,auth.id,body,Date.now());this.save();return reply(result,200,headers);}
 const id=url.searchParams.get('characterId')||account.active;let p=ownedPlayer(this.world,auth.id,id);
 if(p&&(p.gmBanned||(p.gmBlockedUntil||0)>Date.now()))return reply({error:p.gmBanned?'관리자가 이 캐릭터의 접속을 차단했습니다.':'관리자가 접속을 종료했습니다. 잠시 후 다시 접속하세요.'},403);
 if(url.pathname==='/api/socket'){if(request.headers.get('Upgrade')?.toLowerCase()!=='websocket')return new Response('WebSocket required',{status:426});if(!p)return reply({needsCharacter:true},401);const [client,server]=Object.values(new WebSocketPair());this.state.acceptWebSocket(server);server.serializeAttachment({id:p.id});this.sessions.set(server,{id:p.id,last:0});p.seen=Date.now();this.start();return new Response(null,{status:101,webSocket:client});}
 if(url.pathname==='/api/chat'){if(!p)return reply({needsCharacter:true},401);const body=await this.body(request);this.chat(p.id,body.text);return reply({ok:true});}
 if(url.pathname==='/api/game'){if(request.method==='GET')return reply(p?snapshot(this.world,p,Date.now()):{needsCharacter:true});const body=await this.body(request);if(body.join){changeAccount(this.world,auth.id,{action:'create',name:body.name,classId:body.classId},Date.now());p=ownedPlayer(this.world,auth.id);this.save();return reply(snapshot(this.world,p!,Date.now()),200,headers);}if(!p)return reply({needsCharacter:true},401);const input=this.input(body),xp=p.xp,level=p.level;tickWorld(this.world,Date.now());applyInput(this.world,p,input,Date.now());if(input.action||p.xp!==xp||p.level!==level)this.save();return reply(snapshot(this.world,p,Date.now()));}
 return new Response('Not found',{status:404});
 }catch(e){return reply({error:e instanceof Error?e.message:'서버 요청에 실패했습니다.'},400);}}
 private async gmRequest(request:Request,url:URL){
  if(!await gmAuthorized(request.headers.get('Authorization'),this.gmToken))return reply({error:'관리자 인증이 필요합니다.'},401);
  const now=Date.now();
  if(request.method==='GET'&&url.pathname==='/api/gm/players'){const query=(url.searchParams.get('q')||'').toLocaleLowerCase();const players=Object.values(this.world.players).filter(p=>!query||p.name.toLocaleLowerCase().includes(query)||p.id.includes(query)).sort((a,b)=>b.seen-a.seen).map(p=>gmSummary(p,now));return reply({players,now,online:players.filter(p=>p.online).length,items:ITEMS,classes:CLASSES.map(c=>({id:c.id,name:c.name})),zones:ZONES.map(z=>({id:z.id,name:z.name}))});}
  if(request.method==='GET'&&url.pathname==='/api/gm/player'){const p=this.world.players[url.searchParams.get('id')||''];return p?reply(gmDetail(p,now)):reply({error:'수호자를 찾을 수 없습니다.'},404);}
  if(request.method==='GET'&&url.pathname==='/api/gm/donations')return reply({requests:(this.world.donations||[]).slice().reverse(),settings:cashSettings(this.world)});
  if(request.method==='POST'&&url.pathname==='/api/gm/settings'){const settings=configureCash(this.world,await this.body(request));this.save();this.broadcast();return reply({ok:true,settings});}
  if(request.method==='POST'&&url.pathname==='/api/gm/donation'){const donation=approveDonation(this.world,await this.body(request),now);this.save();this.broadcast();return reply({ok:true,donation});}
  if(request.method==='GET'&&url.pathname==='/api/gm/audit')return reply({entries:(this.world.gmAudit||[]).slice().reverse()});
  if(request.method==='GET'&&url.pathname==='/api/gm/backup')return reply({schema:'aetheria-world',exportedAt:now,world:this.world});
  if(request.method==='POST'&&url.pathname==='/api/gm/action'){try{const body=await this.body(request),player=gmMutate(this.world,body,now);this.save();if(body.action==='kick'||body.action==='ban'){for(const [ws,s] of this.sessions)if(s.id===player.id){ws.close(4003,'GM restriction');this.sessions.delete(ws);}}this.broadcast();return reply({ok:true,player});}catch(e){const message=e instanceof Error?e.message:'수정 실패';return reply({error:message==='REVISION_CONFLICT'?'다른 관리자 작업이 반영되었습니다. 새로고침 후 다시 시도하세요.':message},message==='REVISION_CONFLICT'?409:400);}}
  return reply({error:'지원하지 않는 관리 경로입니다.'},404);
 }
 private async body(request:Request){const text=await request.text();if(text.length>4096)throw new Error('요청이 너무 큽니다.');return JSON.parse(text);}
 private input(body:Input):Input{if(!body||typeof body!=='object'||(body.action!==undefined&&typeof body.action!=='string')||(body.targetId!==undefined&&typeof body.targetId!=='string')||(body.tradeId!==undefined&&typeof body.tradeId!=='string')||(body.reference!==undefined&&(typeof body.reference!=='string'||body.reference.length>160))||(body.indices!==undefined&&(!Array.isArray(body.indices)||body.indices.length>12||body.indices.some(n=>!Number.isSafeInteger(n)))))throw new Error('잘못된 요청입니다.');if(!Number.isSafeInteger(body.seq)||body.seq!<0)throw new Error('잘못된 입력입니다.');for(const key of ['moveX','moveY','dx','dy','tx','ty','skill','value','slot','gold','revision'] as const)if(body[key]!==undefined&&!Number.isFinite(body[key]))throw new Error('잘못된 좌표입니다.');return body;}
 webSocketMessage(ws:WebSocket,message:string|ArrayBuffer){const s=this.sessions.get(ws);if(!s)return;try{if(typeof message!=='string'||message.length>4096){ws.close(1009,'Message too large');return;}const body=JSON.parse(message);if(body.kind==='chat'){this.chat(s.id,body.text);return;}const now=Date.now();if(now-s.last<65){ws.send(JSON.stringify({retry:true}));return;}s.last=now;const p=this.world.players[s.id];if(!p)return;if(p.gmBanned||(p.gmBlockedUntil||0)>now){ws.close(4003,'GM restriction');return;}const input=this.input(body),xp=p.xp,level=p.level;tickWorld(this.world,now);applyInput(this.world,p,input,now);if(input.action||p.xp!==xp||p.level!==level)this.save();ws.send(JSON.stringify(snapshot(this.world,p,now)));}catch{ws.send(JSON.stringify({error:'잘못된 요청입니다.'}));}}
 webSocketClose(ws:WebSocket){this.sessions.delete(ws);this.save();}
 webSocketError(ws:WebSocket){this.sessions.delete(ws);this.save();}
}
export default {fetch(request:Request,env:Env){const url=new URL(request.url);if(url.pathname.startsWith('/api/'))return env.REALM.get(env.REALM.idFromName('aetheria-world-v5')).fetch(request);return env.ASSETS.fetch(request);}};
